[
    AVAExecuteAsynchronouseAttribute(AVAExecuteAsynchronouseType::HandoverDoc)
]
 class AVAExecuteAsynchronous_HandoverDoc extends AVAExecuteAsynchronous
{
    AVAHandoverDocTable             handoverDocTable;
    WHSPackingWorkLocationSetup    packingWorkLocationSetup;

}

Method.Source:
public void doExecute()
{
    Args                        args        = new Args();
    AVAHandoverDocController    controller  = new AVAHandoverDocController();

    if (packingWorkLocationSetup.AVAPrintHandoverDocument != AVAPrintDocumentMode::No)
    {
        args.record(handoverDocTable);
        controller.parmArgs(args);
        controller.parmReportName(ssrsReportStr(AVAHandoverDocReport, Report));
        controller.parmShowDialog(false);
        controller.parmShowReportViewerParameters(false);
        controller.parmLoadFromSysLastValue(false);
        controller.parmReportContract().parmPrintSettings(packingWorkLocationSetup.avaGetPrinterSettings());

        controller.startOperation();
    }
}

protected void initFromContract()
{
    if (executeAsynchronousContract.parmCallerRecord()
     && executeAsynchronousContract.parmCallerRecord()
     && executeAsynchronousContract.parmCallerRecord().TableId == tableNum(AVAHandoverDocTable))
    {
        handoverDocTable            = executeAsynchronousContract.parmCallerRecord();
        packingWorkLocationSetup    =  handoverDocTable.packingWorkLocationSetup();
    }
    else
    {
        throw error(Error::wrongUseOfFunction(funcName()));
    }
}
